+			score += 5
+		}
+		for term, weight := range weights {
+			switch {
+			case strings.Contains(name, term):
+				score += weight * 2
+			case strings.Contains(base, term):
+				score += weight
+			case strings.Contains(path, term):
+				score += max(1, weight/2)
+			}
+		}
