        if not command_start:
            continue
        if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*=.*", token):
            continue
        command_start = False
        name = pathlib.Path(token).name
        if name in {"entire", "entire-brain", "entire-graph"}:
            findings.append(name)
    return findings


