	for _, rel := range paths {
		lower := strings.ToLower(rel)
		base := strings.TrimSuffix(strings.ToLower(filepath.Base(rel)), strings.ToLower(filepath.Ext(rel)))
		score := 0
		baseHits := 0
		for _, term := range terms {
			frequency := frequencies[term]
