func semanticQueryTokens(query string) []string {
	seen := map[string]struct{}{}
	var tokens []string
	add := func(token string) bool {
		if len(token) < 3 || historyQueryStopword(token) {
			return true
		}
		if _, ok := seen[token]; ok {
			return true
		}
