			}
		}
		toolKeys[name] = keys
	}
	for name, keys := range toolKeys {
		schemaArgs := map[string]any{}
		for key := range keys {
			schemaArgs[key] = true
		}
		if err := validateMCPToolArguments(name, schemaArgs); err != nil {
			t.Fatalf("%s validator rejected advertised schema args %v: %v", name, keys, err)
