func distillSessionCacheKey(branch, sessionID string) string {
	return url.PathEscape(branch) + "/" + url.PathEscape(sessionID)
}

func cachedDistillSessionFingerprint(cache distillCache, branch, sessionID string) (string, bool) {
	if cache.Sessions == nil {
		return "", false
	}
	fp, ok := cache.Sessions[distillSessionCacheKey(branch, sessionID)]
	// No legacy-key fallback here: a legacy-FORMAT fingerprint can never equal
	// a new-format one, so returning it only manufactures false mismatches.
	// Pre-upgrade entries are honored by grandfatheredDistillFingerprint.
	return fp, ok
}

// readBrainRelativeFile reads a brain-relative path, rejecting absolute paths
// parent-directory escapes, and symlink hops so a manifest-supplied path cannot
// read outside the brain directory.
func readBrainRelativeFile(brainDir, rel string) (string, error) {
	clean := filepath.Clean(filepath.FromSlash(rel))
	if filepath.IsAbs(clean) || clean == "." || clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("unsafe transcript path: %s", rel)
	}
	if err := rejectSymlinkPathComponents(brainDir, clean); err != nil {
		return "", err
	}
	data, err := os.ReadFile(filepath.Join(brainDir, clean))
	if err != nil {
		return "", err
	}
	return string(data), nil
}

// loadDistillCache reads the incremental cache, always returning a usable value:
// any read/parse error or version mismatch yields an empty cache so the next
// run simply re-distills everything.
func loadDistillCache(brainDir string) distillCache {
	empty := distillCache{Version: distillCacheVersion, Sessions: map[string]string{}}
	data, err := os.ReadFile(filepath.Join(brainDir, filepath.FromSlash(distillCachePath)))
	if err != nil {
		return empty
	}
	var cache distillCache
	if err := json.Unmarshal(data, &cache); err != nil || cache.Version != distillCacheVersion || cache.Sessions == nil {
	manifest.CheckpointsScanned = sessions.CheckpointsScanned
	manifest.Branches = append([]exportBranch(nil), sessions.Branches...)
	manifest.Sessions = append([]exportSession(nil), sessions.Sessions...)
	manifest.Warnings = append([]string(nil), sessions.Warnings...)
}

func writeBrainManifestAndReadme(outputDir string, manifest exportManifest) error {
	normalizeBrainManifest(&manifest)
	manifest.SchemaVersion = brainManifestSchemaVersion
	data, err := json.MarshalIndent(manifest, "", "  ")
	if err != nil {
		return fmt.Errorf("encode %s: %w", exportManifestFileName, err)
	}
	data = append(data, '\n')
	if err := writeBrainRelativeFileAtomic(outputDir, exportManifestFileName, data, 0o600); err != nil {
		return fmt.Errorf("write %s: %w", exportManifestFileName, err)
	}
	if err := writeBrainRelativeFileAtomic(outputDir, exportReadmeFileName, []byte(renderBrainReadme(manifest)), 0o600); err != nil {
		return fmt.Errorf("write brain readme: %w", err)
	}
	return nil
}

func cleanBrainRelativePath(rel string) (string, error) {
	clean := filepath.Clean(filepath.FromSlash(rel))
	if filepath.IsAbs(clean) || clean == "." || clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("path is outside brain: %s", rel)
	}
	return clean, nil
}

func writeBrainRelativeFileAtomic(brainDir, rel string, data []byte, perm os.FileMode) error {
	if err := rejectSymlinkedBrainRoot(brainDir); err != nil {
		return err
	}
	clean, err := cleanBrainRelativePath(rel)
	if err != nil {
		return err
	}
	dir := filepath.Dir(clean)
	if dir != "." {
		if err := rejectExistingSymlinkPathComponents(brainDir, dir); err != nil {
			return err
		}
	}
	abs := filepath.Join(brainDir, clean)
	if err := os.MkdirAll(filepath.Dir(abs), 0o700); err != nil {
		return err
	}
	if err := rejectExistingSymlinkPathComponents(brainDir, clean); err != nil {
		return err
	}
	return writeFileAtomic(abs, data, perm)
}

func prepareBrainRelativeSQLiteFile(brainDir, rel string) (string, error) {
	if err := rejectSymlinkedBrainRoot(brainDir); err != nil {
		return "", err
	}
	clean, err := cleanBrainRelativePath(rel)
	if err != nil {
		return "", err
	}
	dir := filepath.Dir(clean)
	if dir != "." {
		if err := rejectExistingSymlinkPathComponents(brainDir, dir); err != nil {
			return "", err
		}
	}
	abs := filepath.Join(brainDir, clean)
	if err := os.MkdirAll(filepath.Dir(abs), 0o700); err != nil {
		return "", err
	}
	if err := rejectExistingSymlinkPathComponents(brainDir, clean); err != nil {
		return "", err
	}
	if err := rejectUnsafeExistingRegularFile(abs, "sqlite cache"); err != nil {
		return "", err
	}
	return abs, nil
}

func removeBrainRelativeFile(brainDir, rel string) error {
	if err := rejectSymlinkedBrainRoot(brainDir); err != nil {
		return err
	}
	clean, err := cleanBrainRelativePath(rel)
	if err != nil {
		return err
	}
	if err := rejectExistingSymlinkPathComponents(brainDir, clean); err != nil {
		return err
	}
	err = os.Remove(filepath.Join(brainDir, clean))
	if err != nil && !os.IsNotExist(err) {
		return err
	}
	return nil
}

func writeFileAtomic(path string, data []byte, perm os.FileMode) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(filepath.Dir(path), "."+filepath.Base(path)+".tmp-*")
	if err != nil {
		t.Fatalf("test suggestions did not follow selected implementation roots: %+v", selected.Suggestions)
	}
}

