		if _, ok := seen[clean]; ok || !slices.Contains(files, clean) {
			return
		}
		seen[clean] = struct{}{}
		out = append(out, clean)
	}
	for _, symbol := range symbols {
		if len(out) >= limit {
			break
		}
		add(symbol.FilePath)
	}
	for _, file := range files {
		if len(out) >= limit {
			break
		}
		add(file)
	}
	return out
}

